<template>
  <main class="page-grid min-h-screen pb-24">
    <section class="max-w-[1440px] mx-auto px-5 md:px-10 pt-16 md:pt-24 pb-14"><p class="font-mono text-[11px] uppercase tracking-[.2em] text-black/55 mb-8">Collaboration desk / 2026</p><div class="grid lg:grid-cols-[1fr_.7fr] gap-10 items-end"><h1 class="font-display text-[clamp(4.5rem,12vw,11rem)] leading-[.78] tracking-[-.1em]">Make<br /><span class="text-[#ff684a]">an impact.</span></h1><p class="max-w-sm text-base leading-relaxed text-black/65">Tell us what you’re building. This is a creative first conversation about the idea, the audience and how Vasu can bring it to life.</p></div></section>
    <section class="bg-[#121212] text-[#f3f0e8] border-y border-black"><div class="max-w-[1440px] mx-auto px-5 md:px-10 py-16 grid md:grid-cols-3 gap-8"><div><p class="font-mono text-[10px] text-white/45 uppercase tracking-[.18em]">01 / Choose a lane</p></div><div class="md:col-span-2 grid sm:grid-cols-2 gap-x-8 gap-y-6"><p v-for="item in services" :key="item" class="font-display text-2xl tracking-[-.05em]"><svg viewBox="0 0 16 16" class="inline-block w-3 h-3 mr-2 text-[#d7ff3f]" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M8 1.5v13M1.5 8h13M3.4 3.4l9.2 9.2M12.6 3.4l-9.2 9.2" stroke-linecap="round"/></svg>{{ item }}</p></div></div></section>
    <div class="max-w-[1440px] mx-auto px-5 md:px-10 pt-16"><form @submit.prevent="submitForm" class="grid lg:grid-cols-[.9fr_1.1fr] gap-12 lg:gap-24"><div><p class="font-mono text-[10px] uppercase tracking-[.18em] text-black/50 mb-5">01 / The brief</p><h2 class="font-display text-5xl md:text-7xl tracking-[-.08em] leading-[.85]">What are we<br /><span class="text-[#ff684a]">making?</span></h2><p class="mt-8 max-w-sm text-sm leading-relaxed text-black/60">Pick the closest fit, then share the thought behind the project. No checkout, no payment step — just the right context to start a meaningful conversation.</p><div class="mt-10 grid sm:grid-cols-2 gap-3"><label v-for="item in serviceOptions" :key="item.value" class="cursor-pointer"><input v-model="form.collab_type" class="peer sr-only" name="collab_type" :value="item.value" :required="item.value === serviceOptions[0].value" type="radio"><span class="block border border-black p-4 text-xs uppercase tracking-[.12em] font-bold transition-colors peer-checked:bg-[#d7ff3f] peer-checked:-translate-y-1">{{ item.label }}</span></label></div></div><div class="bg-white border border-black p-6 md:p-10"><p class="font-mono text-[10px] uppercase tracking-[.18em] text-black/50 mb-8">02 / Start the conversation</p><div class="space-y-7"><div><label for="name" class="block font-mono text-[10px] uppercase tracking-[.16em] mb-2">Your name</label><input id="name" v-model="form.name" required type="text" placeholder="Name" class="field"></div><div><label for="brand" class="block font-mono text-[10px] uppercase tracking-[.16em] mb-2">Brand / company</label><input id="brand" v-model="form.brand" required type="text" placeholder="Company" class="field"></div><div><label for="mobile" class="block font-mono text-[10px] uppercase tracking-[.16em] mb-2">Mobile number</label><input id="mobile" v-model="form.mobile" required type="tel" placeholder="+91 ..." class="field"></div><div><label for="message" class="block font-mono text-[10px] uppercase 