  </main>
</template>

<script setup>
import { reactive, ref, computed } from 'vue'
const services = ['Short-form content', 'RJ / VJ hosting', 'Live events', 'Brand ambassador', 'Product stories', 'Something custom']
const serviceOptions = [{ label: 'Short-form content', value: 'reel' }, { label: 'RJ / VJ', value: 'vj_rj' }, { label: 'Event hosting', value: 'event' }, { label: 'Brand ambassador', value: 'ambassador' }, { label: 'Product review', value: 'review' }, { label: 'Something custom', value: 'other' }]
const form = reactive({ collab_type: '', name: '', brand: '', mobile: '', message: '' })
const isSubmitting = ref(false); const isSuccess = ref(false)
const buttonText = computed(() => isSuccess.value ? 'Conversation started' : isSubmitting.value ? 'Sending...' : 'Start the conversation')
const submitForm = async () => { isSubmitting.value = true; try { const response = await fetch('/api/submit-collab', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) }); if (!response.ok) throw new Error('Submit failed'); isSuccess.value = true; setTimeout(() => { isSuccess.value = false; Object.keys(form).forEach(key => { form[key] = '' }) }, 3000) } catch (error) { console.error(error); alert('Something went wrong. Please try again.') } finally { isSubmitting.value = false } }
</script>

